        <script>
            const uiActions = {
                zoomAndOpen: function(element) {
                    element.classList.add("zoomed");
                    // 1. Calculate the click position for a natural zoom
                    const rect = element.getBoundingClientRect();
                    const xPct = ((event.clientX - rect.left) / rect.width) * 100;
                    const yPct = ((event.clientY - rect.top) / rect.height) * 100;

                    // Create a GSAP Timeline for perfect sequencing
                    const tl = gsap.timeline();

                    gsap.to(".places-graph .item:not(.zoomed)", {
                        opacity: 0.3,
                    });
                    // 2. Zoom the image
                    tl.to(element, {
                        scale: 2.5,
                        transformOrigin: `${xPct}% ${yPct}%`,
                        duration: 1,
                        ease: "power2.inOut"
                    })
                    .add(() => {
                        document.body.classList.add('show-zoomed-view');
                        element.classList.remove("zoomed");
                    }).to(element, {
                        scale: 1,
                        transformOrigin: "center center",
                        duration: 0.4,
                        ease: "power2.out",
                    })
                    .to(".places-graph .item", { 
                        opacity: 1, 
                    });
                },
            };
            document.body.addEventListener('click', async (e) => {
                const trigger = e.target.closest("[data-area-view]");
                if (trigger) {
                    e.preventDefault();
                    const dataURL = trigger.getAttribute("data-area-view");
                    try {
                        const response = await fetch(dataURL);
                        if (!response.ok) throw new Error('Network response was not ok');
                        const data = await response.text();

                        trigger.closest(".view").querySelector(".area-column").innerHTML = data;
                    } catch (error) {
                        console.log("something went wrong");
                    }        
                }
            });
            function activeZoomedView(view) {
                setTimeout(function(){
                    document.body.classList.add('show-zoomed-view');
                    document.querySelector(".places-area").setAttribute("data-view", view);
                }, 800);
            }
            function closeZoomedView() {
                document.querySelectorAll(".zoom-image").forEach(item => {
                    item.classList.remove("zoomed");
                });
                document.body.classList.remove("show-zoomed-view");
                document.querySelector('.places-area').classList.remove('show-left-col');
            }
            document.addEventListener("DOMContentLoaded", function() {
                const gallery_thumbnails = new Swiper(".gallery-modal .thumbnails", {
                    spaceBetween: 12,
                    slidesPerView: 2,
                    loop: true,
                    freeMode: true,
                    watchSlidesProgress: true,
                    breakpoints: {
                        992: {
                            slidesPerView: 3,
                        },
                        1200: {
                            slidesPerView: 4,
                            spaceBetween: 24,
                        },
                    }
                });

                const gallery_main_preview = new Swiper(".gallery-modal .main-preview .swiper", {
                    spaceBetween: 0,
                    slidesPerView: 1,
                    loop: true,
                    thumbs: {
                        swiper: gallery_thumbnails
                    },
                    navigation: {
                        nextEl: ".gallery-modal .arrows .next",
                        prevEl: ".gallery-modal .arrows .prev",
                    }
                });
            });
        </script>
